const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeMenindee = ee.Geometry.Polygon([
    [142.35, -32.25],
    [142.45, -32.25],
    [142.45, -32.35],
    [142.35, -32.35],
    [142.35, -32.25]
  ]);

  const date1 = '2019-02-02';
  const date2 = '2021-05-14';

  // 2. Data Acquisition
  function getWaterArea(date) {
    const collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(lakeMenindee)
      .filterDate(date, ee.Date(date).advance(1, 'month'));

    const size = collection.size().getInfo();
    if (size === 0) {
      return {area: null, pixels: 0, images: 0, status: 'no_images'};
    }

    // Get least cloudy image
    const image = collection.sort('CLOUDY_PIXEL_PERCENTAGE').first();

    // Cloud masking
    const cloudMask = image.select('MSK_CLDPRB').lt(20);
    const maskedImage = image.updateMask(cloudMask);

    // Calculate NDWI for water detection
    const ndwi = maskedImage.normalizedDifference(['B3', 'B8']).rename('NDWI');

    // Water threshold (NDWI > 0 typically indicates water)
    const water = ndwi.gt(0.1);

    // Count water pixels
    const stats = water.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: lakeMenindee,
      scale: 20,
      maxPixels: 1e9
    });

    const waterPixels = stats.get('NDWI').getInfo();

    return {area: waterPixels, pixels: waterPixels, images: size, status: 'success'};
  }

  // Get water areas for both dates
  const area2019 = getWaterArea(date1);
  const area2021 = getWaterArea(date2);

  // 3. Check for data issues
  if (area2019.status === 'no_images' || area2021.status === 'no_images') {
    console.log(`2019 Images: ${area2019.images} (Area: ${area2019.area})`);
    console.log(`2021 Images: ${area2021.images} (Area: ${area2021.area})`);
    console.log("<answer>C1</answer>");
    return;
  }

  if (area2019.pixels === 0 || area2021.pixels === 0) {
    console.log(`2019 Water Pixels: ${area2019.pixels}`);
    console.log(`2021 Water Pixels: ${area2021.pixels}`);
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Validation & Final Answer
  console.log(`2019 Water Area: ${area2019.area.toFixed(0)} pixels`);
  console.log(`2021 Water Area: ${area2021.area.toFixed(0)} pixels`);
  console.log(`Change: ${((area2021.area - area2019.area) / area2019.area * 100).toFixed(1)}%`);

  // Check if shrank (2021 area < 2019 area)
  if (area2021.area < area2019.area) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
